using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using GameClient;
using Xunit;

namespace GameClientTests
{
    // fixtures.json is generated by `node js/make-fixtures.mjs` from the real CarrierDominion
    // engine/heightmap.js: islands from a captured match (+ one high-seed island), each sampled
    // on a grid over island/shore/shelf/sea and on rings at the radius and skirt edges.
    // Sample rows are [islandIndex, wx, wy, expectedHeight].
    public class HeightmapPortTests
    {
        static readonly JsonElement F =
            JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "fixtures.json"))).RootElement;

        static readonly List<Island> Islands = Load();

        static List<Island> Load()
        {
            var list = new List<Island>();
            foreach (JsonElement e in F.GetProperty("islands").EnumerateArray())
            {
                list.Add(new Island
                {
                    id = e.GetProperty("id").GetInt32(), x = e.GetProperty("x").GetInt32(), y = e.GetProperty("y").GetInt32(),
                    radius = e.GetProperty("radius").GetInt32(), peak = e.GetProperty("peak").GetInt32(),
                    seed = e.GetProperty("seed").GetInt32(), noiseCell = e.GetProperty("noiseCell").GetInt32(),
                    noiseOctaves = e.GetProperty("noiseOctaves").GetInt32(), noisePermil = e.GetProperty("noisePermil").GetInt32(),
                    warpCell = e.GetProperty("warpCell").GetInt32(), warpPermil = e.GetProperty("warpPermil").GetInt32(),
                });
            }
            return list;
        }

        static void CheckIslands(Func<int, bool> which)
        {
            int n = 0;
            foreach (JsonElement s in F.GetProperty("samples").EnumerateArray())
            {
                int i = s[0].GetInt32();
                if (!which(i)) continue;
                long wx = s[1].GetInt64(), wy = s[2].GetInt64(), expected = s[3].GetInt64();
                long actual = Heightmap.IslandHeightAt(Islands[i], wx, wy);
                Assert.True(expected == actual, $"island {i} at ({wx}, {wy}): got {actual}, JS gives {expected}");
                n++;
            }
            Assert.True(n > 1000, $"only {n} samples checked");
        }

        [Fact]
        public void SkirtRadius_MatchesJavaScript()
        {
            int i = 0;
            foreach (JsonElement s in F.GetProperty("skirts").EnumerateArray())
                Assert.Equal(s.GetInt64(), Heightmap.SkirtRadius(Islands[i++]));
        }

        [Fact]
        public void CapturedIslands_EveryHeightMatchesJavaScript()
        {
            CheckIslands(i => i < 8);
        }

        [Fact]
        public void IslandWithSeedNearIntMax_MatchesJavaScript()
        {
            // worldgen draws seeds from [0, 2147483646]; a seed near the top of that range.
            CheckIslands(i => i == 8);
        }

        [Fact]
        public void FarOutAtSea_IsTheFlatSeabed()
        {
            Island isl = Islands[0];
            Assert.Equal(-51200, Heightmap.IslandHeightAt(isl, isl.x + 50L * isl.radius, isl.y));
        }
    }
}
